    "tgp1": {
      "backLink": "← 返回项目",
      "tagLabel": "游戏项目",
      "gameName": "Detective Folder",
      "image": "../images/detective-folder-hero.jpg",
      "roleLabel": "角色",
      "role": "关卡策划",
      "teamSizeLabel": "团队规模",
      "teamSize": "5 人",
      "lengthLabel": "项目周期",
      "length": "1 学期",
      "platformLabel": "平台",
      "platform": "PC — Unity（SMU Guildhall）",
      "synopsisHeading": "游戏简介",
      "synopsis": "Detective Folder 是一款由 5 人学生团队用 Unity 制作的 2D 解谜平台游戏。玩家扮演神秘「异常犯罪调查组」的侦探，通过折叠这个如漫画书般鲜活的世界来改变平台形态、收集线索，最终抓捕「Baahd Guys」。",
      "trailerHeading": "预告片",
      "trailerNote": "游戏预告片。",
      "trailerVideoId": "caEVKftmSHA",
      "responsibilitiesHeading": "主要职责",
      "responsibilities": [
        "设计了教程关卡、第一关的后半部分，以及整个第三关和第四关，循序渐进地引入并强化游戏的核心折叠机制。",
        "在初期头脑风暴阶段提出并主导了「折叠」这一核心机制，探索其在空间移动和解谜深度上的多种应用。",
        "与团队程序员密切合作，在确定关卡布局前明确技术限制，并协助排查实现过程中的问题。",
        "在团队出现早期人际摩擦时主动促成坦诚沟通，根据每位队友的沟通风格调整自己的方式。",
        "参与 GDD/LDD 文档编写，并协助美术团队统一视觉方向。"
      ],
      "screenshotsHeading": "游戏截图",
      "screenshotsNote": "教程关卡、第三关的对角线折叠迷宫，以及第四关的恐龙遭遇战。",
      "screenshots": [
        "../images/detective-folder/shot-2.jpg",
        "../images/detective-folder/shot-3.jpg",
        "../images/detective-folder/shot-4.jpg",
        "../images/detective-folder/shot-1.jpg"
      ],
      "postmortemHeading": "项目复盘",
      "postmortem": "从最初的概念构思到贯穿四个关卡的实现，主导折叠机制的过程教会了我把失败当作数据来看待——由于这类机制没有太多现成参考，我采用了「快速失败」的方法保持高速迭代。最大的教训在于范围管理：像第四关的恐龙这样的功能虽然有趣，但成本很高，如果没有严格的资产锁定纪律，我们就会把时间花在制造视觉效果上，而不是打磨核心体验。我也学到了应该更早引入玩家测试——等我们发现玩家在新手引导上遇到困难时，已经太晚了，只能仓促重做教程关卡。归根结底，这个项目让我明白了预生产阶段的技术验证，以及清晰文档作为团队「唯一真相来源」的价值，这对于一个正在摸索全新机制的团队来说尤为重要。"
    },
